script:
(() => {
  const COLORS = ["#2563eb", "#0891b2", "#0f766e", "#d97706", "#7c3aed", "#db2777", "#4d7c0f", "#ea580c"];
  const card = root_element.querySelector(".designation-treemap");
  if (!card) return;

  const body = card.querySelector(".designation-treemap__body");
  const plot = card.querySelector("[data-plot]");
  const legend = card.querySelector("[data-legend]");
  const state = card.querySelector("[data-state]");
  const totalElement = card.querySelector("[data-total]");
  const refreshButton = card.querySelector(".designation-treemap__refresh");
  const numberFormatter = new Intl.NumberFormat("vi-VN");
  let selectedBranches = Array.isArray(window.__vntHrWorkspaceBranches)
    ? [...window.__vntHrWorkspaceBranches]
    : (window.__vntHrWorkspaceBranch ? [window.__vntHrWorkspaceBranch] : []);
  let selectedDate = window.__vntHrWorkspaceDate || frappe.datetime.get_today();

  function bindWorkspaceFilters(reload) {
    const eventName = "vnt-hr-filter-change";
    if (root_element.__vntHrFilterHandler) document.removeEventListener(eventName, root_element.__vntHrFilterHandler);
    const handler = (event) => {
      if (!root_element.isConnected) {
        document.removeEventListener(eventName, handler);
        return;
      }
      const detail = (event && event.detail) || {};
      const nextBranches = Array.isArray(detail.branches)
        ? detail.branches.map(String)
        : (detail.branch ? [String(detail.branch)] : []);
      const nextDate = String(detail.as_of_date || frappe.datetime.get_today());
      if (JSON.stringify(nextBranches) === JSON.stringify(selectedBranches) && nextDate === selectedDate) return;
      selectedBranches = nextBranches;
      selectedDate = nextDate;
      reload();
    };
    root_element.__vntHrFilterHandler = handler;
    document.addEventListener(eventName, handler);
  }

  async function getSnapshot() {
    const company = frappe.defaults.get_user_default("Company") || "";
    const key = [selectedDate, selectedBranches.join("\u001f"), company].join("|");
    const cache = window.__vntHrSnapshotCache || (window.__vntHrSnapshotCache = {});
    const cached = cache[key];
    if (cached && Date.now() - cached.createdAt < 2000) return cached.promise;
    const promise = frappe.xcall("vinatex.api.hr_dashboard.get_hr_dashboard_snapshot", {
      as_of_date: selectedDate,
      branches: selectedBranches,
      company
    });
    cache[key] = { createdAt: Date.now(), promise };
    try { return await promise; }
    catch (error) { delete cache[key]; throw error; }
  }

  let currentItems = [];
  let renderFrame = 0;

  function showState(message, isError) {
    state.textContent = message;
    state.classList.toggle("is-error", Boolean(isError));
    state.hidden = false;
    body.hidden = true;
  }

  function layout(nodes, x, y, width, height, output) {
    if (!nodes.length || width <= 0 || height <= 0) return;
    if (nodes.length === 1) {
      output.push({ item: nodes[0], x: x, y: y, width: width, height: height });
      return;
    }

    const total = nodes.reduce((sum, node) => sum + node.value, 0);
    let running = 0;
    let splitIndex = 1;
    let bestDistance = Infinity;

    for (let index = 0; index < nodes.length - 1; index += 1) {
      running += nodes[index].value;
      const distance = Math.abs(total / 2 - running);
      if (distance < bestDistance) {
        bestDistance = distance;
        splitIndex = index + 1;
      }
    }

    const first = nodes.slice(0, splitIndex);
    const second = nodes.slice(splitIndex);
    const firstTotal = first.reduce((sum, node) => sum + node.value, 0);
    const ratio = total ? firstTotal / total : 0.5;

    if (width >= height) {
      const firstWidth = width * ratio;
      layout(first, x, y, firstWidth, height, output);
      layout(second, x + firstWidth, y, width - firstWidth, height, output);
    } else {
      const firstHeight = height * ratio;
      layout(first, x, y, width, firstHeight, output);
      layout(second, x, y + firstHeight, width, height - firstHeight, output);
    }
  }

  function drawTreemap() {
    cancelAnimationFrame(renderFrame);
    renderFrame = requestAnimationFrame(() => {
      if (!currentItems.length || !plot.isConnected) return;
      const width = plot.clientWidth;
      const height = plot.clientHeight;
      if (!width || !height) return;

      const rectangles = [];
      layout(currentItems, 0, 0, width, height, rectangles);
      plot.textContent = "";

      rectangles.forEach((rectangle, index) => {
        const item = rectangle.item;
        const tile = document.createElement("div");
        const percentage = item.percentage;
        const compact = rectangle.width < 125 || rectangle.height < 66;
        const tiny = rectangle.width < 62 || rectangle.height < 38;

        tile.className = "designation-treemap__tile" + (compact ? " is-compact" : "") + (tiny ? " is-tiny" : "");
        tile.style.left = rectangle.x + "px";
        tile.style.top = rectangle.y + "px";
        tile.style.width = rectangle.width + "px";
        tile.style.height = rectangle.height + "px";
        tile.style.background = item.color;
        tile.style.animationDelay = index * 45 + "ms";
        tile.title = item.label + ": " + numberFormatter.format(item.value) + " nhân sự (" + percentage + "%)";
        tile.setAttribute("aria-label", tile.title);

        const label = document.createElement("span");
        label.className = "designation-treemap__tile-label";
        label.textContent = item.label;

        const value = document.createElement("span");
        value.className = "designation-treemap__tile-value";
        value.textContent = numberFormatter.format(item.value);
        const share = document.createElement("small");
        share.textContent = percentage + "%";
        value.appendChild(share);

        tile.appendChild(label);
        tile.appendChild(value);
        plot.appendChild(tile);
      });
    });
  }

  function render(rows) {
    const items = rows
      .map((row) => ({
        label: String(row.designation || "Chưa xác định"),
        value: Number(row.employee_count) || 0
      }))
      .filter((item) => item.value > 0)
      .sort((a, b) => b.value - a.value);

    if (!items.length) {
      totalElement.textContent = "0";
      showState("Chưa có dữ liệu để hiển thị.", false);
      return;
    }

    const total = items.reduce((sum, item) => sum + item.value, 0);
    currentItems = items.map((item, index) => ({
      label: item.label,
      value: item.value,
      percentage: total ? Math.round(item.value / total * 100) : 0,
      color: COLORS[index % COLORS.length]
    }));

    totalElement.textContent = numberFormatter.format(total);
    legend.textContent = "";

    currentItems.forEach((item) => {
      const row = document.createElement("div");
      row.className = "designation-treemap__legend-row";
      row.setAttribute("role", "listitem");
      row.title = item.label;

      const dot = document.createElement("span");
      dot.className = "designation-treemap__dot";
      dot.style.background = item.color;

      const label = document.createElement("span");
      label.className = "designation-treemap__legend-label";
      label.textContent = item.label;

      const value = document.createElement("span");
      value.className = "designation-treemap__legend-value";
      value.textContent = numberFormatter.format(item.value);
      const share = document.createElement("small");
      share.textContent = item.percentage + "%";
      value.appendChild(share);

      row.appendChild(dot);
      row.appendChild(label);
      row.appendChild(value);
      legend.appendChild(row);
    });

    body.hidden = false;
    state.hidden = true;
    drawTreemap();
  }

  async function load() {
    refreshButton.disabled = true;
    showState("Đang tải dữ liệu…", false);

    try {
      const response = await getSnapshot();
      const data = (response && response.dimensions && response.dimensions.designation_group) || {};
      const labels = Array.isArray(data.labels) ? data.labels : [];
      const values = data.datasets && data.datasets[0] && Array.isArray(data.datasets[0].values)
        ? data.datasets[0].values : [];
      render(labels.map((label, index) => ({ designation: label, employee_count: values[index] })));
    } catch (error) {
      console.error("Không thể tải dữ liệu nhóm chức danh", error);
      showState("Không thể tải dữ liệu. Vui lòng thử lại.", true);
    } finally {
      refreshButton.disabled = false;
    }
  }

  const resizeObserver = new ResizeObserver(() => {
    if (!card.isConnected) {
      resizeObserver.disconnect();
      return;
    }
    drawTreemap();
  });
  resizeObserver.observe(plot);

  refreshButton.addEventListener("click", load);
  bindWorkspaceFilters(load);
  load();
})();

style:
:host {
  display: block;
  min-width: 0;
  max-width: 100%;
  height: 100%;
}

* {
  box-sizing: border-box;
}

.designation-treemap {
  min-width: 0;
  max-width: 100%;
  container-type: inline-size;
  min-height: 310px;
  height: 100%;
  padding: 14px 16px 16px;
  color: var(--text-color);
  background: var(--card-bg);
  border: 0;
  border-radius: 12px;
  overflow: hidden;
}

.designation-treemap__header,
.designation-treemap__actions,
.designation-treemap__legend-row {
  display: flex;
  align-items: center;
}

.designation-treemap__header {
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.designation-treemap__header > :first-child {
  min-width: 0;
}

.designation-treemap__header h3 {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
}

.designation-treemap__header p {
  margin: 3px 0 0;
  color: var(--text-muted);
  font-size: 12px;
}

.designation-treemap__actions {
  flex: 0 0 auto;
  gap: 8px;
}

.designation-treemap__total {
  padding: 5px 9px;
  color: #1d4ed8;
  background: #eff6ff;
  border-radius: 999px;
  font-size: 10px;
  white-space: nowrap;
}

.designation-treemap__total strong {
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.designation-treemap__refresh {
  width: 30px;
  height: 30px;
  padding: 0;
  color: var(--text-muted);
  background: var(--control-bg);
  border: 1px solid transparent;
  border-radius: 8px;
  font-size: 18px;
  line-height: 1;
  cursor: pointer;
}

.designation-treemap__refresh:hover {
  color: var(--primary);
  border-color: var(--border-color);
}

.designation-treemap__refresh:disabled {
  cursor: wait;
  opacity: 0.55;
}

.designation-treemap__body {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(0, 0.9fr);
  gap: 13px;
  height: 230px;
}

.designation-treemap__plot {
  position: relative;
  min-width: 0;
  height: 230px;
  overflow: hidden;
  background: var(--control-bg);
  border-radius: 10px;
}

.designation-treemap__tile {
  position: absolute;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  min-width: 0;
  min-height: 0;
  padding: 9px;
  overflow: hidden;
  color: #fff;
  border: 2px solid var(--card-bg);
  border-radius: 8px;
  cursor: default;
  isolation: isolate;
  transition: filter 160ms ease, transform 160ms ease;
  animation: designation-tile-in 360ms ease-out both;
}

.designation-treemap__tile::after {
  position: absolute;
  inset: 35% 0 0;
  z-index: -1;
  background: linear-gradient(transparent, rgba(15, 23, 42, 0.32));
  content: "";
}

.designation-treemap__tile:hover {
  z-index: 2;
  filter: brightness(1.08);
  transform: translateY(-1px);
}

.designation-treemap__tile-label {
  display: -webkit-box;
  overflow: hidden;
  font-size: 11px;
  font-weight: 600;
  line-height: 1.25;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.designation-treemap__tile-value {
  margin-top: 4px;
  font-size: 17px;
  font-weight: 750;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.designation-treemap__tile-value small {
  margin-left: 4px;
  font-size: 9px;
  font-weight: 600;
  opacity: 0.86;
}

.designation-treemap__tile.is-compact {
  padding: 6px;
}

.designation-treemap__tile.is-compact .designation-treemap__tile-label {
  font-size: 9px;
  -webkit-line-clamp: 1;
}

.designation-treemap__tile.is-compact .designation-treemap__tile-value {
  margin-top: 2px;
  font-size: 12px;
}

.designation-treemap__tile.is-tiny .designation-treemap__tile-label,
.designation-treemap__tile.is-tiny small {
  display: none;
}

.designation-treemap__legend {
  display: grid;
  align-content: start;
  gap: 3px;
  min-width: 0;
  max-height: 230px;
  padding-right: 3px;
  overflow-y: auto;
  scrollbar-width: thin;
}

.designation-treemap__legend-row {
  display: grid;
  grid-template-columns: 9px minmax(0, 1fr) auto;
  gap: 7px;
  min-height: 25px;
  padding: 3px 2px;
  border-bottom: 1px solid var(--border-color);
}

.designation-treemap__dot {
  width: 8px;
  height: 8px;
  border-radius: 3px;
}

.designation-treemap__legend-label {
  min-width: 0;
  overflow: hidden;
  font-size: 10px;
  font-weight: 500;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.designation-treemap__legend-value {
  font-size: 10px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.designation-treemap__legend-value small {
  display: block;
  color: var(--text-muted);
  font-size: 8px;
  font-weight: 500;
}

.designation-treemap__state {
  padding: 76px 12px;
  color: var(--text-muted);
  font-size: 12px;
  text-align: center;
}

.designation-treemap__state.is-error {
  color: var(--red-600, #dc2626);
}

.designation-treemap__state[hidden],
.designation-treemap__body[hidden] {
  display: none;
}

@container (max-width: 430px) {
  .designation-treemap__total { display: none; }
}

@keyframes designation-tile-in {
  from { opacity: 0; transform: scale(0.96); }
  to { opacity: 1; transform: scale(1); }
}

@media (max-width: 560px) {
  .designation-treemap__body {
    grid-template-columns: 1fr;
    height: auto;
  }

  .designation-treemap__plot {
    height: 190px;
  }

  .designation-treemap__legend {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    max-height: 96px;
  }

  .designation-treemap__total {
    display: none;
  }
}

[class$="__refresh"] img {
  display: block;
  width: 16px;
  height: 16px;
  opacity: .9;
}

script:
(() => {
  const COLORS = ["#f59e0b", "#ec4899", "#2563eb", "#22c55e", "#64748b"];
  const SVG_NS = "http://www.w3.org/2000/svg";
  const card = root_element.querySelector(".age-donut");
  if (!card) return;

  const body = card.querySelector(".age-donut__body");
  const arcsElement = card.querySelector("[data-arcs]");
  const legendElement = card.querySelector("[data-legend]");
  const state = card.querySelector("[data-state]");
  const totalElement = card.querySelector("[data-total]");
  const centerTotalElement = card.querySelector("[data-center-total]");
  const refreshButton = card.querySelector(".age-donut__refresh");
  const numberFormatter = new Intl.NumberFormat("vi-VN");
  let selectedBranches = Array.isArray(window.__vntHrWorkspaceBranches)
    ? [...window.__vntHrWorkspaceBranches]
    : (window.__vntHrWorkspaceBranch ? [window.__vntHrWorkspaceBranch] : []);
  let selectedDate = window.__vntHrWorkspaceDate || frappe.datetime.get_today();

  function bindWorkspaceFilters(reload) {
    const eventName = "vnt-hr-filter-change";
    if (root_element.__vntHrFilterHandler) document.removeEventListener(eventName, root_element.__vntHrFilterHandler);
    const handler = (event) => {
      if (!root_element.isConnected) {
        document.removeEventListener(eventName, handler);
        return;
      }
      const detail = (event && event.detail) || {};
      const nextBranches = Array.isArray(detail.branches)
        ? detail.branches.map(String)
        : (detail.branch ? [String(detail.branch)] : []);
      const nextDate = String(detail.as_of_date || frappe.datetime.get_today());
      if (JSON.stringify(nextBranches) === JSON.stringify(selectedBranches) && nextDate === selectedDate) return;
      selectedBranches = nextBranches;
      selectedDate = nextDate;
      reload();
    };
    root_element.__vntHrFilterHandler = handler;
    document.addEventListener(eventName, handler);
  }

  async function getSnapshot() {
    const company = frappe.defaults.get_user_default("Company") || "";
    const key = [selectedDate, selectedBranches.join("\u001f"), company].join("|");
    const cache = window.__vntHrSnapshotCache || (window.__vntHrSnapshotCache = {});
    const cached = cache[key];
    if (cached && Date.now() - cached.createdAt < 2000) return cached.promise;
    const promise = frappe.xcall("vinatex.api.hr_dashboard.get_hr_dashboard_snapshot", {
      as_of_date: selectedDate,
      branches: selectedBranches,
      company
    });
    cache[key] = { createdAt: Date.now(), promise };
    try { return await promise; }
    catch (error) { delete cache[key]; throw error; }
  }


  function showState(message, isError) {
    state.textContent = message;
    state.classList.toggle("is-error", Boolean(isError));
    state.hidden = false;
    body.hidden = true;
  }

  function percentageText(value) {
    return value > 0 && value < 1 ? "<1%" : Math.round(value) + "%";
  }

  function setActive(index, active) {
    const arc = arcsElement.querySelector('[data-index="' + index + '"]');
    const row = legendElement.querySelector('[data-index="' + index + '"]');
    if (arc) arc.classList.toggle("is-active", active);
    if (row) row.classList.toggle("is-active", active);
  }

  function render(data) {
    const labels = Array.isArray(data && data.labels) ? data.labels : [];
    const datasets = Array.isArray(data && data.datasets) ? data.datasets : [];
    const values = datasets[0] && Array.isArray(datasets[0].values) ? datasets[0].values : [];
    const items = labels
      .map((label, index) => ({
        label: String(label || "Chưa xác định"),
        value: Number(values[index]) || 0
      }))
      .filter((item) => item.value > 0);

    if (!items.length) {
      totalElement.textContent = "0";
      centerTotalElement.textContent = "0";
      showState("Chưa có dữ liệu để hiển thị.", false);
      return;
    }

    const total = items.reduce((sum, item) => sum + item.value, 0);
    let offset = 0;
    arcsElement.textContent = "";
    legendElement.textContent = "";
    totalElement.textContent = numberFormatter.format(total);
    centerTotalElement.textContent = numberFormatter.format(total);

    items.forEach((item, index) => {
      const exactPercentage = total ? item.value / total * 100 : 0;
      const share = percentageText(exactPercentage);
      const color = COLORS[index % COLORS.length];
      const description = item.label + ": " + numberFormatter.format(item.value) + " nhân sự (" + share + ")";

      const circle = document.createElementNS(SVG_NS, "circle");
      circle.setAttribute("class", "age-donut__arc");
      circle.setAttribute("cx", "110");
      circle.setAttribute("cy", "110");
      circle.setAttribute("r", "72");
      circle.setAttribute("pathLength", "100");
      circle.setAttribute("stroke", color);
      circle.setAttribute("stroke-dasharray", exactPercentage + " " + (100 - exactPercentage));
      circle.setAttribute("stroke-dashoffset", String(-offset));
      circle.setAttribute("data-index", String(index));
      circle.style.animationDelay = index * 75 + "ms";

      const title = document.createElementNS(SVG_NS, "title");
      title.textContent = description;
      circle.appendChild(title);
      arcsElement.appendChild(circle);

      const row = document.createElement("div");
      row.className = "age-donut__legend-row";
      row.setAttribute("role", "listitem");
      row.setAttribute("data-index", String(index));
      row.title = description;

      const dot = document.createElement("span");
      dot.className = "age-donut__dot";
      dot.style.background = color;

      const label = document.createElement("span");
      label.className = "age-donut__legend-label";
      label.textContent = item.label;

      const value = document.createElement("span");
      value.className = "age-donut__legend-value";
      value.textContent = numberFormatter.format(item.value);
      const small = document.createElement("small");
      small.textContent = share;
      value.appendChild(small);

      row.appendChild(dot);
      row.appendChild(label);
      row.appendChild(value);
      legendElement.appendChild(row);

      circle.addEventListener("mouseenter", () => setActive(index, true));
      circle.addEventListener("mouseleave", () => setActive(index, false));
      row.addEventListener("mouseenter", () => setActive(index, true));
      row.addEventListener("mouseleave", () => setActive(index, false));

      offset += exactPercentage;
    });

    body.hidden = false;
    state.hidden = true;
  }

  async function load() {
    refreshButton.disabled = true;
    showState("Đang tải dữ liệu…", false);

    try {
      const response = await getSnapshot();
      render(response && response.dimensions ? response.dimensions.age : null);
    } catch (error) {
      console.error("Không thể tải dữ liệu độ tuổi", error);
      showState("Không thể tải dữ liệu. Vui lòng thử lại.", true);
    } finally {
      refreshButton.disabled = false;
    }
  }

  refreshButton.addEventListener("click", load);
  bindWorkspaceFilters(load);
  load();
})();

