script:
(() => {
  const COLORS = ["#ef4444", "#f59e0b", "#84cc16", "#ec4899", "#2563eb"];
  const PLOT_HEIGHT = 130;
  const card = root_element.querySelector(".seniority-columns");
  if (!card) return;

  const chartElement = card.querySelector(".seniority-columns__chart");
  const axisElement = card.querySelector("[data-axis]");
  const guidesElement = card.querySelector("[data-guides]");
  const barsElement = card.querySelector("[data-bars]");
  const state = card.querySelector("[data-state]");
  const totalElement = card.querySelector("[data-total]");
  const refreshButton = card.querySelector(".seniority-columns__refresh");
  const numberFormatter = new Intl.NumberFormat("vi-VN");
  let selectedBranches = Array.isArray(window.__vntHrWorkspaceBranches)
    ? [...window.__vntHrWorkspaceBranches]
    : (window.__vntHrWorkspaceBranch ? [window.__vntHrWorkspaceBranch] : []);
  let selectedDate = window.__vntHrWorkspaceDate || frappe.datetime.get_today();

  function bindWorkspaceFilters(reload) {
    const eventName = "vnt-hr-filter-change";
    if (root_element.__vntHrFilterHandler) document.removeEventListener(eventName, root_element.__vntHrFilterHandler);
    const handler = (event) => {
      if (!root_element.isConnected) {
        document.removeEventListener(eventName, handler);
        return;
      }
      const detail = (event && event.detail) || {};
      const nextBranches = Array.isArray(detail.branches)
        ? detail.branches.map(String)
        : (detail.branch ? [String(detail.branch)] : []);
      const nextDate = String(detail.as_of_date || frappe.datetime.get_today());
      if (JSON.stringify(nextBranches) === JSON.stringify(selectedBranches) && nextDate === selectedDate) return;
      selectedBranches = nextBranches;
      selectedDate = nextDate;
      reload();
    };
    root_element.__vntHrFilterHandler = handler;
    document.addEventListener(eventName, handler);
  }

  async function getSnapshot() {
    const company = frappe.defaults.get_user_default("Company") || "";
    const key = [selectedDate, selectedBranches.join("\u001f"), company].join("|");
    const cache = window.__vntHrSnapshotCache || (window.__vntHrSnapshotCache = {});
    const cached = cache[key];
    if (cached && Date.now() - cached.createdAt < 2000) return cached.promise;
    const promise = frappe.xcall("vinatex.api.hr_dashboard.get_hr_dashboard_snapshot", {
      as_of_date: selectedDate,
      branches: selectedBranches,
      company
    });
    cache[key] = { createdAt: Date.now(), promise };
    try { return await promise; }
    catch (error) { delete cache[key]; throw error; }
  }


  function showState(message, isError) {
    state.textContent = message;
    state.classList.toggle("is-error", Boolean(isError));
    state.hidden = false;
    chartElement.hidden = true;
  }

  function percentageText(value) {
    return value > 0 && value < 1 ? "<1%" : Math.round(value) + "%";
  }

  function niceStep(maximum) {
    const rough = maximum / 5;
    const magnitude = Math.pow(10, Math.floor(Math.log10(rough)));
    const residual = rough / magnitude;
    const factor = residual <= 1 ? 1 : residual <= 2 ? 2 : residual <= 5 ? 5 : 10;
    return factor * magnitude;
  }

  function renderAxis(scaleMaximum, step) {
    axisElement.textContent = "";
    guidesElement.textContent = "";

    for (let value = 0; value <= scaleMaximum; value += step) {
      const position = value / scaleMaximum;

      const label = document.createElement("span");
      label.className = "seniority-columns__axis-label";
      label.style.setProperty("--position", String(position));
      label.textContent = numberFormatter.format(value);
      axisElement.appendChild(label);

      const guide = document.createElement("span");
      guide.className = "seniority-columns__guide";
      guide.style.setProperty("--position", String(position));
      guidesElement.appendChild(guide);
    }
  }

  function render(data) {
    const labels = Array.isArray(data && data.labels) ? data.labels : [];
    const datasets = Array.isArray(data && data.datasets) ? data.datasets : [];
    const values = datasets[0] && Array.isArray(datasets[0].values) ? datasets[0].values : [];
    const items = labels
      .map((label, index) => ({
        label: String(label || "Chưa xác định"),
        value: Number(values[index]) || 0,
        color: COLORS[index % COLORS.length]
      }))
      .filter((item) => item.value > 0);

    if (!items.length) {
      totalElement.textContent = "0";
      showState("Chưa có dữ liệu để hiển thị.", false);
      return;
    }

    const total = items.reduce((sum, item) => sum + item.value, 0);
    const maximum = Math.max(...items.map((item) => item.value));
    const step = niceStep(maximum);
    const scaleMaximum = Math.ceil(maximum / step) * step;

    totalElement.textContent = numberFormatter.format(total);
    barsElement.textContent = "";
    renderAxis(scaleMaximum, step);

    items.forEach((item, index) => {
      const percentage = total ? item.value / total * 100 : 0;
      const height = item.value / scaleMaximum * PLOT_HEIGHT;
      const description = item.label + ": " + numberFormatter.format(item.value) +
        " nhân sự (" + percentageText(percentage) + ")";

      const wrapper = document.createElement("div");
      wrapper.className = "seniority-columns__item";
      wrapper.setAttribute("role", "listitem");
      wrapper.setAttribute("aria-label", description);
      wrapper.title = description;
      wrapper.style.setProperty("--height", height + "px");
      wrapper.style.setProperty("--color", item.color);
      wrapper.style.setProperty("--delay", index * 70 + "ms");

      const barSpace = document.createElement("div");
      barSpace.className = "seniority-columns__bar-space";

      const bar = document.createElement("span");
      bar.className = "seniority-columns__bar";

      const value = document.createElement("span");
      value.className = "seniority-columns__value";
      value.textContent = numberFormatter.format(item.value);
      const share = document.createElement("small");
      share.textContent = percentageText(percentage);
      value.appendChild(share);

      const label = document.createElement("div");
      label.className = "seniority-columns__label";
      label.textContent = item.label;

      barSpace.appendChild(bar);
      barSpace.appendChild(value);
      wrapper.appendChild(barSpace);
      wrapper.appendChild(label);
      barsElement.appendChild(wrapper);
    });

    chartElement.hidden = false;
    state.hidden = true;
  }

  async function load() {
    refreshButton.disabled = true;
    showState("Đang tải dữ liệu…", false);

    try {
      const response = await getSnapshot();
      render(response && response.dimensions ? response.dimensions.seniority : null);
    } catch (error) {
      console.error("Không thể tải dữ liệu thâm niên", error);
      showState("Không thể tải dữ liệu. Vui lòng thử lại.", true);
    } finally {
      refreshButton.disabled = false;
    }
  }

  refreshButton.addEventListener("click", load);
  bindWorkspaceFilters(load);
  load();
})();

