script:
(() => {
  const card = root_element.querySelector(".hr-reminders");
  if (!card) return;

  const daysAhead = Number(card.dataset.days || 30);
  const limit = Number(card.dataset.limit || 100);
  const refreshButton = card.querySelector(".hr-reminders__refresh");
  const stateElement = card.querySelector("[data-state]");
  const numberFormatter = new Intl.NumberFormat("vi-VN");
  let selectedBranches = Array.isArray(window.__vntHrWorkspaceBranches)
    ? [...window.__vntHrWorkspaceBranches]
    : (window.__vntHrWorkspaceBranch ? [window.__vntHrWorkspaceBranch] : []);
  let selectedDate = window.__vntHrWorkspaceDate || frappe.datetime.get_today();

  function bindWorkspaceFilters(reload) {
    const eventName = "vnt-hr-filter-change";
    if (root_element.__vntHrFilterHandler) document.removeEventListener(eventName, root_element.__vntHrFilterHandler);
    const handler = (event) => {
      if (!root_element.isConnected) {
        document.removeEventListener(eventName, handler);
        return;
      }
      const detail = (event && event.detail) || {};
      const nextBranches = Array.isArray(detail.branches)
        ? detail.branches.map(String)
        : (detail.branch ? [String(detail.branch)] : []);
      const nextDate = String(detail.as_of_date || frappe.datetime.get_today());
      if (JSON.stringify(nextBranches) === JSON.stringify(selectedBranches) && nextDate === selectedDate) return;
      selectedBranches = nextBranches;
      selectedDate = nextDate;
      reload();
    };
    root_element.__vntHrFilterHandler = handler;
    document.addEventListener(eventName, handler);
  }

  async function getSnapshot() {
    const company = frappe.defaults.get_user_default("Company") || "";
    const key = [selectedDate, selectedBranches.join("\u001f"), company].join("|");
    const cache = window.__vntHrSnapshotCache || (window.__vntHrSnapshotCache = {});
    const cached = cache[key];
    if (cached && Date.now() - cached.createdAt < 2000) return cached.promise;
    const promise = frappe.xcall("vinatex.api.hr_dashboard.get_hr_dashboard_snapshot", {
      as_of_date: selectedDate,
      branches: selectedBranches,
      company
    });
    cache[key] = { createdAt: Date.now(), promise };
    try { return await promise; }
    catch (error) { delete cache[key]; throw error; }
  }


  card.querySelector("[data-days-label]").textContent = numberFormatter.format(daysAhead);

  function reportUrl(name, filters) {
    return `/app/query-report/${encodeURIComponent(name)}?filters=${encodeURIComponent(JSON.stringify(filters))}`;
  }

  function renderItem(key, count, url) {
    const item = card.querySelector(`[data-reminder="${key}"]`);
    const countElement = item.querySelector("[data-count]");
    const linkElement = item.querySelector("[data-link]");
    const emptyElement = item.querySelector("[data-empty]");

    countElement.textContent = numberFormatter.format(count);
    linkElement.href = url;
    linkElement.hidden = count <= 0;
    emptyElement.hidden = count > 0;
  }

  async function load() {
    refreshButton.disabled = true;
    stateElement.hidden = true;
    card.querySelectorAll("[data-count]").forEach((element) => { element.textContent = "…"; });

    try {
      const data = await frappe.xcall("vinatex.api.hr_reminders.get_hr_reminders", {
        days_ahead: daysAhead,
        limit,
        branches: selectedBranches,
        as_of_date: selectedDate
      });
      const counts = (data && data.counts) || {};
      const fromDate = selectedDate;
      const toDate = frappe.datetime.add_days(fromDate, daysAhead);
      const baseFilters = { from_date: fromDate, to_date: toDate };
      const contractFilters = { ...baseFilters, include_expired_before_from_date: 0 };
      const retirementFilters = {
        from_date: fromDate,
        to_date: frappe.datetime.add_days(fromDate, 365)
      };
      if (selectedBranches.length === 1) {
        baseFilters.branch = selectedBranches[0];
        contractFilters.branch = selectedBranches[0];
        retirementFilters.branch = selectedBranches[0];
      }

      renderItem("contracts", Number(counts.contracts ?? (data.contracts_expiring || []).length) || 0,
        reportUrl("Hợp đồng sắp hết hạn", contractFilters));
      renderItem("birthdays", Number(counts.birthdays ?? (data.birthdays || []).length) || 0,
        reportUrl("Danh sách sinh nhật", baseFilters));
      renderItem("retirements", Number(counts.retirements ?? (data.retirements || []).length) || 0,
        reportUrl("Báo cáo cán bộ đến tuổi nghỉ hưu", retirementFilters));
    } catch (error) {
      console.error("Không thể tải nhắc nhở nhân sự", error);
      card.querySelectorAll("[data-count]").forEach((element) => { element.textContent = "–"; });
      stateElement.textContent = "Không thể tải dữ liệu nhắc nhở. Vui lòng thử lại.";
      stateElement.hidden = false;
    } finally {
      refreshButton.disabled = false;
    }
  }

  refreshButton.addEventListener("click", load);
  bindWorkspaceFilters(load);
  load();
})();

