script:
(() => {
  const card = root_element.querySelector(".hr-turnover");
  if (!card) return;

  const chartElement = card.querySelector("[data-chart]");
  const stateElement = card.querySelector("[data-state]");
  const refreshButton = card.querySelector(".hr-turnover__refresh");
  const formatter = new Intl.NumberFormat("vi-VN");
  let selectedBranches = Array.isArray(window.__vntHrWorkspaceBranches)
    ? [...window.__vntHrWorkspaceBranches]
    : (window.__vntHrWorkspaceBranch ? [window.__vntHrWorkspaceBranch] : []);
  let selectedDate = window.__vntHrWorkspaceDate || frappe.datetime.get_today();

  function bindWorkspaceFilters(reload) {
    const eventName = "vnt-hr-filter-change";
    if (root_element.__vntHrFilterHandler) document.removeEventListener(eventName, root_element.__vntHrFilterHandler);
    const handler = (event) => {
      if (!root_element.isConnected) {
        document.removeEventListener(eventName, handler);
        return;
      }
      const detail = (event && event.detail) || {};
      const nextBranches = Array.isArray(detail.branches)
        ? detail.branches.map(String)
        : (detail.branch ? [String(detail.branch)] : []);
      const nextDate = String(detail.as_of_date || frappe.datetime.get_today());
      if (JSON.stringify(nextBranches) === JSON.stringify(selectedBranches) && nextDate === selectedDate) return;
      selectedBranches = nextBranches;
      selectedDate = nextDate;
      reload();
    };
    root_element.__vntHrFilterHandler = handler;
    document.addEventListener(eventName, handler);
  }

  async function getSnapshot() {
    const company = frappe.defaults.get_user_default("Company") || "";
    const key = [selectedDate, selectedBranches.join("\u001f"), company].join("|");
    const cache = window.__vntHrSnapshotCache || (window.__vntHrSnapshotCache = {});
    const cached = cache[key];
    if (cached && Date.now() - cached.createdAt < 2000) return cached.promise;
    const promise = frappe.xcall("vinatex.api.hr_dashboard.get_hr_dashboard_snapshot", {
      as_of_date: selectedDate,
      branches: selectedBranches,
      company
    });
    cache[key] = { createdAt: Date.now(), promise };
    try { return await promise; }
    catch (error) { delete cache[key]; throw error; }
  }

  let chart = null;


  function showState(message, isError) {
    stateElement.textContent = message;
    stateElement.classList.toggle("is-error", Boolean(isError));
    stateElement.hidden = false;
    chartElement.hidden = true;
  }

  function setSummary(hiring, attrition) {
    const totalHire = hiring.reduce((sum, value) => sum + value, 0);
    const totalLeft = attrition.reduce((sum, value) => sum + value, 0);
    const net = totalHire - totalLeft;
    card.querySelector("[data-total-hire]").textContent = formatter.format(totalHire);
    card.querySelector("[data-total-left]").textContent = formatter.format(totalLeft);
    card.querySelector("[data-total-net]").textContent = (net > 0 ? "+" : "") + formatter.format(net);
    card.querySelector(".hr-turnover__pill--net").style.setProperty("--pill-color", net >= 0 ? "#15803d" : "#dc2626");
  }

  function render(rows) {
    const normalized = rows
      .filter((row) => row && !Array.isArray(row))
      .map((row) => ({
        month: String(row.month || row["Tháng"] || "").replace(/^(\d{2})-(\d{4})$/, "$1/$2"),
        hiring: Number(row.hiring_count ?? row["Tuyển dụng"]) || 0,
        attrition: Number(row.attrition_count ?? row["Nghỉ việc"]) || 0
      }));

    if (!normalized.length) {
      setSummary([], []);
      showState("Chưa có dữ liệu biến động nhân sự.", false);
      return;
    }

    const labels = normalized.map((row) => row.month);
    const hiring = normalized.map((row) => row.hiring);
    const attrition = normalized.map((row) => row.attrition);
    setSummary(hiring, attrition);

    chartElement.textContent = "";
    chartElement.hidden = false;
    stateElement.hidden = true;

    chart = new frappe.Chart(chartElement, {
      data: {
        labels,
        datasets: [
          { name: "Tuyển mới", values: hiring },
          { name: "Nghỉ việc", values: attrition }
        ]
      },
      type: "line",
      height: 228,
      colors: ["#60a5fa", "#8b5cf6"],
      axisOptions: { xAxisMode: "tick", yAxisMode: "span", xIsSeries: 1 },
      lineOptions: { regionFill: 1, hideDots: 0, dotSize: 4 },
      tooltipOptions: {
        formatTooltipY: (value) => formatter.format(value) + " nhân sự"
      },
      animate: 1
    });
  }

  async function load() {
    refreshButton.disabled = true;
    showState("Đang tải dữ liệu…", false);

    try {
      const filters = {
        from_date: frappe.datetime.add_months(frappe.datetime.month_start(selectedDate), -11),
        to_date: selectedDate
      };
      const company = frappe.defaults.get_default("company");
      if (company) filters.company = company;
      if (selectedBranches.length) filters.branches = selectedBranches;

      const response = await frappe.xcall("frappe.desk.query_report.run", {
        report_name: "NS tuyển mới với nghỉ việc",
        filters,
        ignore_prepared_report: 1
      });
      render(Array.isArray(response && response.result) ? response.result : []);
    } catch (error) {
      console.error("Không thể tải biểu đồ tuyển mới và nghỉ việc", error);
      showState("Không thể tải dữ liệu. Vui lòng thử lại.", true);
    } finally {
      refreshButton.disabled = false;
    }
  }

  refreshButton.addEventListener("click", load);
  bindWorkspaceFilters(load);
  load();
})();

(() => {
  const card = root_element.querySelector(".hr-branch-filter");
  if (!card) return;

  const BRANCHES_STORAGE_KEY = "vnt.hr.workspace.branches";
  const LEGACY_BRANCH_STORAGE_KEY = "vnt.hr.workspace.branch";
  const DATE_STORAGE_KEY = "vnt.hr.workspace.date";
  const EVENT_NAME = "vnt-hr-filter-change";
  const dateInput = card.querySelector("[data-date-input]");
  const today = frappe.datetime.get_today();
  let selectedDate = today;

  try {
    selectedDate = window.sessionStorage.getItem(DATE_STORAGE_KEY) || today;
  } catch (error) {
    selectedDate = window.__vntHrWorkspaceDate || today;
  }
  if (!/^\d{4}-\d{2}-\d{2}$/.test(selectedDate) || selectedDate > today) selectedDate = today;
  dateInput.max = today;
  dateInput.value = selectedDate;

  function broadcast() {
    window.__vntHrWorkspaceBranches = [];
    window.__vntHrWorkspaceBranch = "";
    window.__vntHrWorkspaceDate = selectedDate;
    try {
      window.sessionStorage.removeItem(BRANCHES_STORAGE_KEY);
      window.sessionStorage.removeItem(LEGACY_BRANCH_STORAGE_KEY);
      window.sessionStorage.setItem(DATE_STORAGE_KEY, selectedDate);
    } catch (error) {
      console.debug("Không thể lưu ngày dữ liệu nhân sự trong phiên", error);
    }
    document.dispatchEvent(new CustomEvent(EVENT_NAME, { detail: {
      branches: [],
      branch: "",
      as_of_date: selectedDate
    }}));
  }

  dateInput.addEventListener("change", () => {
    selectedDate = dateInput.value || today;
    if (selectedDate > today) selectedDate = today;
    dateInput.value = selectedDate;
    broadcast();
  });

  broadcast();
})();

