  box-sizing: border-box;
  width: 100%;
  height: 38px;
  padding: 0 10px;
  color: #1e293b;
  background: #fff;
  border: 1px solid #bfdbfe;
  border-radius: 10px;
  outline: none;
  font-size: 13px;
  cursor: pointer;
}
.hr-branch-filter__date-wrap input:focus {
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, .14);
}
@media (max-width: 900px) {
  .hr-branch-filter__date-wrap { width: 180px; min-width: 0; }
}
@media (max-width: 520px) {
  .hr-branch-filter__date-wrap { width: 100%; }
}

/* Multi-branch picker */
.hr-branch-filter { position: relative; z-index: 4; overflow: visible; }
.hr-branch-filter__field-label { margin: 0; color: #475569; font-size: 13px; font-weight: 600; white-space: nowrap; }
.hr-branch-filter__select-wrap { z-index: 5; }
.hr-branch-filter__trigger {
  width: 100%; height: 38px; padding: 0 11px 0 12px; display: flex; align-items: center;
  justify-content: space-between; gap: 10px; color: #1e293b; background: #fff;
  border: 1px solid #bfdbfe; border-radius: 10px; outline: none; font-size: 13px;
  text-align: left; cursor: pointer;
}
.hr-branch-filter__trigger > span:first-child { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.hr-branch-filter__trigger:focus, .hr-branch-filter__select-wrap.is-open .hr-branch-filter__trigger {
  border-color: #3b82f6; box-shadow: 0 0 0 3px rgba(59, 130, 246, .14);
}
.hr-branch-filter__trigger:disabled { color: #94a3b8; cursor: wait; }
.hr-branch-filter__menu {
  position: absolute; top: calc(100% + 5px); left: 0; z-index: 50; box-sizing: border-box;
  width: 100%; max-height: 285px; padding: 6px; overflow-y: auto; color: #1e293b;
  background: #fff; border: 1px solid #cbd5e1; border-radius: 10px;
  box-shadow: 0 16px 34px rgba(15, 23, 42, .18);
}
.hr-branch-filter__menu[hidden] { display: none; }
.hr-branch-filter__option {
  min-height: 34px; margin: 0; padding: 7px 8px; display: flex; align-items: center;
  gap: 9px; border-radius: 7px; font-size: 13px; font-weight: 500; cursor: pointer;
}
.hr-branch-filter__option:hover { background: #eff6ff; }
.hr-branch-filter__option--all {
  margin-bottom: 4px; border-bottom: 1px solid #e2e8f0; border-radius: 7px 7px 0 0; font-weight: 650;
}
.hr-branch-filter__option input { width: 16px; height: 16px; margin: 0; flex: 0 0 16px; accent-color: #4f46e5; }
.hr-branch-filter__options { display: grid; gap: 1px; }
